<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Activity, ArrowDown, ArrowRight, ArrowUpRight, Check, ChevronDown, Crosshair, Gamepad2, Map, Moon, Play, ShieldCheck, Sparkles, Sun, Swords, Target, Trophy, Users } from '@lucide/vue'
import BrandMark from './components/BrandMark.vue'
import { getPublicServers } from './api'
import type { PublicGameServer } from './api'
import { websiteSettings } from './websiteSettings'

defineProps<{ darkTheme:boolean }>()
const emit=defineEmits<{ authRequested:[mode:'login'|'register']; themeRequested:[] }>()
const root=ref<HTMLElement|null>(null)
const enhanced=ref(false)
const activePreview=ref('match')
const openFaq=ref<string|null>(null)
const servers=ref<PublicGameServer[]>([])
const serverState=ref<'loading'|'ready'|'unavailable'>('loading')
let observer:IntersectionObserver|undefined
let disposed=false
const previews=computed(()=>[
  {id:'match',label:'Матчи',icon:Swords,kicker:'КАЖДЫЙ РАУНД НА СВОЁМ МЕСТЕ',title:'Весь матч. До последнего фрага.',description:'Счёт, карты серии, MVP и результаты каждого игрока. Во время игры следи за live-счётом, после — разбирай свой матч.',points:['Live-счёт и история матчей','Classic, BO1, BO3 и BO5','Результаты игроков по каждой карте'],image:'match',alt:'Пример War-серии с результатами карт и статистикой игроков'},
  ...(websiteSettings.value.lobbyEnabled?[{id:'lobby',label:'Лобби',icon:Users,kicker:'ТВОЯ КОМАНДА УЖЕ ЖДЁТ',title:'Собери своих. Задай правила.',description:'Создай комнату, выбери карты и формат. Пригласи друзей, займите места в командах — и выходите на сервер с готовым составом.',points:['От 1 × 1 до 5 × 5','Свои карты, серия и пароль комнаты','Уровень и ELO будущих тиммейтов'],image:'lobby',alt:'Пример комнаты лобби с двумя командами, уровнями и ELO игроков'}]:[]),
  {id:'profile',label:'Профиль',icon:Activity,kicker:'ПРОГРЕСС, КОТОРЫЙ ВИДНО',title:'Твоя история становится больше.',description:'Рейтинг War, история ELO, любимые карты и подробная статистика. Открой профиль и посмотри, как меняется твоя игра.',points:['Уровень и рейтинг ELO в War','ADR, KAST, K/D и статистика оружия','Активность и история Mix- и War-матчей'],image:'profile',alt:'Пример статистики игрока с рейтингом ELO, показателями и графиком прогресса'},
])
const preview=computed(()=>previews.value.find(item=>item.id===activePreview.value) ?? previews.value[0]!)
const visibleServers=computed(()=>servers.value.slice(0,websiteSettings.value.serversLimit))
const online=computed(()=>{const responding=servers.value.filter(server=>server.playersOnline!==null);return responding.length?responding.reduce((sum,server)=>sum+(server.playersOnline??0),0):null})
const features=computed(()=>[
  {icon:Swords,title:'Mix и War',text:'Выбирай темп своей игры'},
  {icon:websiteSettings.value.lobbyEnabled?Users:Map,title:websiteSettings.value.lobbyEnabled?'Свои лобби':'Серии карт',text:websiteSettings.value.lobbyEnabled?'Твоя команда, твои правила':'От Classic до BO5'},
  {icon:Trophy,title:'War-рейтинг ELO',text:'Каждая победа — шаг вперёд'},
  {icon:Crosshair,title:'Статистика игрока',text:'Разбирай игру в деталях'},
])
function scrollTo(id:string) { document.getElementById(id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}) }
function selectPreview(index:number,focus=false) {
  const item=previews.value[(index+previews.value.length)%previews.value.length]!
  activePreview.value=item.id
  if(focus) document.getElementById(`landing-tab-${item.id}`)?.focus()
}
function tilt(event:PointerEvent) {
  if(event.pointerType==='touch'||matchMedia('(prefers-reduced-motion: reduce)').matches) return
  const element=event.currentTarget as HTMLElement,rect=element.getBoundingClientRect()
  element.style.setProperty('--tilt-x',`${(0.5-(event.clientY-rect.top)/rect.height)*3}deg`)
  element.style.setProperty('--tilt-y',`${((event.clientX-rect.left)/rect.width-0.5)*3}deg`)
}
function resetTilt(event:PointerEvent) { const element=event.currentTarget as HTMLElement;element.style.setProperty('--tilt-x','0deg');element.style.setProperty('--tilt-y','0deg') }
onMounted(async()=>{
  if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches) {
    observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer?.unobserve(entry.target)}}),{threshold:0.08})
    root.value?.querySelectorAll('[data-reveal]').forEach(element=>observer?.observe(element))
    enhanced.value=true
  }
  if(!websiteSettings.value.serversLimit){serverState.value='ready';return}
  try { const data=await getPublicServers();if(!disposed){servers.value=data;serverState.value='ready'} }
  catch { if(!disposed)serverState.value='unavailable' }
})
onBeforeUnmount(()=>{disposed=true;observer?.disconnect()})
</script>

<template>
  <div ref="root" class="landing-page" :class="{'is-enhanced':enhanced}">
    <header class="landing-header"><div class="landing-header-inner"><a class="landing-brand" href="#top" :aria-label="`${websiteSettings.name} — главная`" @click.prevent="scrollTo('top')"><BrandMark /><span>{{ websiteSettings.name }}<small>{{ websiteSettings.tagline }}</small></span></a><nav aria-label="Разделы лендинга"><a href="#platform" @click.prevent="scrollTo('platform')">Возможности</a><a href="#how-to-play" @click.prevent="scrollTo('how-to-play')">Как начать</a><a v-if="websiteSettings.faq.length" href="#landing-faq" @click.prevent="scrollTo('landing-faq')">Вопросы</a></nav><div class="landing-header-actions"><button class="landing-theme" type="button" :aria-label="darkTheme?'Включить светлую тему':'Включить тёмную тему'" :aria-pressed="darkTheme" @click="emit('themeRequested')"><Sun v-if="darkTheme" :size="17"/><Moon v-else :size="17"/></button><button class="landing-login" type="button" @click="emit('authRequested','login')">Войти <ArrowUpRight :size="15"/></button><button class="landing-button landing-header-join" type="button" @click="emit('authRequested','register')">Начать играть <ArrowRight :size="15"/></button></div></div></header>

    <section class="landing-hero landing-container" aria-labelledby="landing-title">
      <div class="landing-hero-orbit" aria-hidden="true"></div><div class="landing-hero-grid" aria-hidden="true"></div>
      <div class="landing-hero-copy"><span class="landing-eyebrow landing-hero-eyebrow"><span class="landing-status-dot"></span>COUNTER-STRIKE: SOURCE <span class="landing-eyebrow-divider">/</span> V34</span><h1 id="landing-title">Твоя игра.<br/><span>Твоя история.</span></h1><p>{{ websiteSettings.description }}</p><div class="landing-hero-actions"><button class="landing-button" type="button" @click="emit('authRequested','register')"><Play :size="17" fill="currentColor"/>Начать играть <ArrowRight :size="18"/></button><a class="landing-button is-secondary" href="#platform" @click.prevent="scrollTo('platform')">Посмотреть площадку <ArrowDown :size="16"/></a></div><div class="landing-hero-notes"><span><Check :size="13"/>Матчи сообщества</span><span><Check :size="13"/>War-рейтинг ELO</span><span><Check :size="13"/>Подробная статистика</span></div></div>
      <div class="landing-hero-stage"><div class="landing-stage-glow" aria-hidden="true"></div><div class="landing-hero-preview" @pointermove="tilt" @pointerleave="resetTilt"><div class="landing-preview-bar"><span class="landing-window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span><ShieldCheck :size="12"/>{{ websiteSettings.name }} / match</span><span class="landing-preview-badge">WAR · BO3</span></div><div class="landing-hero-screenshot"><img class="landing-shot is-dark" src="/images/landing/match-dark.webp" width="1280" height="880" alt="Пример War-матча: счёт серии, карты и результаты игроков" fetchpriority="high"/><img class="landing-shot is-light" src="/images/landing/match-light.webp" width="1280" height="880" alt="Пример War-матча: счёт серии, карты и результаты игроков" fetchpriority="high"/></div><div class="landing-preview-footer"><span><span class="landing-status-dot"></span>От первого раунда до MVP</span><span>Демонстрационный матч</span></div></div><div class="landing-floating-card is-rating" aria-hidden="true"><img src="/icons/levels/level-10.svg" alt="" width="42" height="42"/><div><small>ТВОЙ СЛЕДУЮЩИЙ УРОВЕНЬ</small><strong>Есть к чему стремиться <ArrowUpRight :size="15"/></strong></div></div><div class="landing-floating-card is-match" aria-hidden="true"><span class="landing-float-icon"><Trophy :size="19"/></span><div><small>КАЖДАЯ ИГРА В ИСТОРИИ</small><strong>Победа — только начало.</strong></div></div></div>
      <div class="landing-feature-strip"><article v-for="feature in features" :key="feature.title"><component :is="feature.icon" :size="21"/><div><strong>{{ feature.title }}</strong><span>{{ feature.text }}</span></div></article></div>
    </section>

    <section id="platform" class="landing-platform landing-container" aria-labelledby="landing-platform-title"><header class="landing-section-heading" data-reveal><div><span class="landing-eyebrow">01 <i></i> ПЛОЩАДКА ИЗНУТРИ</span><h2 id="landing-platform-title">Для тех, кто<br/>живёт игрой.</h2></div><p>От готового состава до последнего фрага —<br class="landing-desktop-break"/>всё, что нужно твоему следующему матчу.</p></header><div class="landing-preview-tabs" role="tablist" aria-label="Превью площадки" data-reveal><button v-for="(item,index) in previews" :id="`landing-tab-${item.id}`" :key="item.id" type="button" role="tab" :aria-selected="preview.id===item.id" :aria-controls="`landing-panel-${item.id}`" :tabindex="preview.id===item.id?0:-1" @click="selectPreview(index)" @keydown.right.prevent="selectPreview(index+1,true)" @keydown.left.prevent="selectPreview(index-1,true)" @keydown.home.prevent="selectPreview(0,true)" @keydown.end.prevent="selectPreview(previews.length-1,true)"><component :is="item.icon" :size="17"/>{{ item.label }}<ArrowUpRight :size="14"/></button></div><div class="landing-showcase" data-reveal><div class="landing-showcase-copy"><Transition name="landing-copy" mode="out-in"><div :key="preview.id"><span class="landing-eyebrow">{{ preview.kicker }}</span><h3>{{ preview.title }}</h3><p>{{ preview.description }}</p><ul><li v-for="point in preview.points" :key="point"><Check :size="15"/>{{ point }}</li></ul><button class="landing-text-button" type="button" @click="emit('authRequested','register')">Присоединиться <ArrowUpRight :size="17"/></button></div></Transition></div><div :id="`landing-panel-${preview.id}`" class="landing-showcase-frame" role="tabpanel" :aria-labelledby="`landing-tab-${preview.id}`" tabindex="0"><div class="landing-preview-bar"><span class="landing-window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>{{ websiteSettings.name }} / {{ preview.id }}</span><Sparkles :size="13"/></div><div class="landing-showcase-image"><Transition name="landing-screen" mode="out-in"><div :key="preview.image"><img class="landing-shot is-dark" :src="`/images/landing/${preview.image}-dark.webp`" :alt="preview.alt" width="1280" height="880" loading="lazy"/><img class="landing-shot is-light" :src="`/images/landing/${preview.image}-light.webp`" :alt="preview.alt" width="1280" height="880" loading="lazy"/></div></Transition></div></div></div><p class="landing-demo-note">Настоящий интерфейс площадки. На превью используются демонстрационные данные.</p></section>

    <section class="landing-progress-section"><div class="landing-container landing-progress-grid"><div class="landing-progress-art" data-reveal><div class="landing-progress-halo" aria-hidden="true"></div><span class="landing-progress-trophy"><Trophy :size="34"/></span><span class="landing-progress-star star-one" aria-hidden="true">✦</span><span class="landing-progress-star star-two" aria-hidden="true">✦</span><span class="landing-progress-star star-three" aria-hidden="true">✦</span><div class="landing-levels" aria-label="Примеры уровней War-рейтинга"><img v-for="level in [3,5,7,9,10]" :key="level" :src="`/icons/levels/level-${level}.svg`" :alt="`Уровень ${level}`" width="76" height="76" loading="lazy"/></div><span class="landing-progress-path" aria-hidden="true"></span><div class="landing-progress-caption"><span>ТВОЯ ИГРА В ЦИФРАХ</span><strong>У каждой победы есть продолжение.</strong></div></div><div class="landing-progress-copy" data-reveal><span class="landing-eyebrow">02 <i></i> СЛЕДИ ЗА ПРОГРЕССОМ</span><h2>Сегодня — хороший матч.<br/><span>Завтра — новый уровень.</span></h2><p>Играй War и развивай свой рейтинг ELO. Сравнивай результаты по картам, находи сильные стороны и возвращайся за новой победой.</p><div class="landing-progress-facts"><span><Target :size="18"/><strong>Точность</strong><small>HS%, оружие и урон</small></span><span><Activity :size="18"/><strong>Вклад в игру</strong><small>ADR, KAST и клатчи</small></span><span><Trophy :size="18"/><strong>Прогресс</strong><small>Уровень и история ELO</small></span></div><button class="landing-text-button" type="button" @click="activePreview='profile'; scrollTo('platform')">Посмотреть профиль игрока <ArrowUpRight :size="17"/></button></div></div></section>

    <section id="how-to-play" class="landing-start landing-container" aria-labelledby="landing-start-title"><header class="landing-section-heading" data-reveal><div><span class="landing-eyebrow">03 <i></i> ТВОЙ ПЕРВЫЙ МАТЧ</span><h2 id="landing-start-title">До игры —<br/>пара простых шагов.</h2></div><span class="landing-section-symbol" aria-hidden="true"><Crosshair :size="40"/></span></header><div class="landing-steps"><article data-reveal><span class="landing-step-number">01</span><div class="landing-step-icon"><Users :size="25"/></div><h3>Создай свой профиль</h3><p>Зарегистрируйся и привяжи Steam ID. Так результаты матчей найдут тебя на площадке.</p></article><article data-reveal><span class="landing-step-number">02</span><div class="landing-step-icon"><Gamepad2 :size="25"/></div><h3>{{ websiteSettings.lobbyEnabled?'Найди свою команду':'Выбери свой матч' }}</h3><p>{{ websiteSettings.lobbyEnabled?'Залетай на Mix-сервер или собирай состав в лобби. Выбери карты, формат и выходи в игру.':'Подключайся к игровому серверу сообщества. Mix для свободной игры, War — для командного соперничества.' }}</p></article><article data-reveal><span class="landing-step-number">03</span><div class="landing-step-icon"><Trophy :size="25"/></div><h3>Играй. Побеждай. Расти.</h3><p>Твои матчи сохраняются в истории. Возвращайся за следующей победой и новым уровнем в War.</p></article></div></section>

    <section v-if="websiteSettings.serversLimit>0" id="landing-servers" class="landing-server-section landing-container" aria-labelledby="landing-servers-title"><header class="landing-section-heading" data-reveal><div><span class="landing-eyebrow"><span class="landing-status-dot"></span> ТОЧКА ВХОДА В ИГРУ</span><h2 id="landing-servers-title">Увидимся на сервере.</h2></div><span v-if="online!==null" class="landing-real-online"><strong>{{ online }}</strong><span>игроков на доступных серверах</span></span></header><div class="landing-public-servers" data-reveal><template v-if="serverState==='ready' && visibleServers.length"><article v-for="server in visibleServers" :key="server.id"><div><span class="landing-server-icon"><Gamepad2 :size="21"/></span><div><h3>{{ server.name }}</h3><span>{{ server.map || 'Карта не получена' }} · {{ server.mode }}</span></div></div><span class="landing-server-population"><Users :size="15"/><strong>{{ server.playersOnline??'—' }}</strong><small>/ {{ server.playerLimit??'—' }}</small></span><a :href="`steam://connect/${server.address}`" :aria-label="`Подключиться к ${server.name}`"><span>В игру</span><ArrowUpRight :size="20"/></a></article></template><div v-else class="landing-server-empty"><Gamepad2 :size="24"/><p>{{ serverState==='loading'?'Смотрим, кто уже в игре…':serverState==='unavailable'?'Список серверов сейчас недоступен. Попробуйте чуть позже.':'Серверы появятся здесь после подключения к площадке.' }}</p><RouterLink to="/matches/mix">Посмотреть матчи <ArrowUpRight :size="15"/></RouterLink></div></div><p class="landing-server-note">Подключение открывается через Steam. В списке — общедоступные игровые серверы.</p></section>

    <section v-if="websiteSettings.faq.length" id="landing-faq" class="landing-faq landing-container" aria-labelledby="landing-faq-title"><div data-reveal><span class="landing-eyebrow">ЕСТЬ ВОПРОСЫ?</span><h2 id="landing-faq-title">Сначала разберёмся.<br/><span>Потом — в игру.</span></h2><p>Всё важное перед первым матчем.</p></div><div class="landing-faq-list" data-reveal><article v-for="item in websiteSettings.faq" :key="item.id" :class="{'is-open':openFaq===item.id}"><h3><button :id="`landing-question-${item.id}`" type="button" :aria-expanded="openFaq===item.id" :aria-controls="`landing-answer-${item.id}`" @click="openFaq=openFaq===item.id?null:item.id">{{ item.question }}<ChevronDown :size="18"/></button></h3><div :id="`landing-answer-${item.id}`" class="landing-faq-answer" :aria-labelledby="`landing-question-${item.id}`" :inert="openFaq!==item.id"><div><p>{{ item.answer }}</p></div></div></article></div></section>

    <section class="landing-final landing-container" data-reveal><div class="landing-final-map" aria-hidden="true"></div><span class="landing-eyebrow"><Sparkles :size="15"/> ТВОЯ ИСТОРИЯ НАЧИНАЕТСЯ ЗДЕСЬ</span><h2>Следующий матч<br/><span>может стать твоим.</span></h2><p>Команда, любимая карта и тот самый раунд.<br/>Осталось только зайти.</p><div class="landing-hero-actions"><button class="landing-button" type="button" @click="emit('authRequested','register')">Создать аккаунт <ArrowRight :size="18"/></button><button class="landing-button is-secondary" type="button" @click="emit('authRequested','login')">Уже с нами? Войти</button></div></section>
    <footer class="landing-footer landing-container"><a class="landing-brand" href="#top" @click.prevent="scrollTo('top')"><BrandMark/><span>{{ websiteSettings.name }}<small>{{ websiteSettings.tagline }}</small></span></a><nav aria-label="Страницы сообщества"><RouterLink to="/matches/mix">Матчи</RouterLink><RouterLink to="/stats">Статистика</RouterLink><RouterLink to="/bans">Баны</RouterLink></nav><span>© {{ new Date().getFullYear() }} {{ websiteSettings.name }}<small>Играть. Соревноваться. Быть командой.</small></span></footer>
  </div>
</template>
